// Coupon: A discount. Codes customers type live in CouponCode. Provider coupons apply
// to that provider's plans. Platform coupons apply across providers.
type Coupon struct {
	// ISO currency to decimal amount for fixed coupons. Never converted.
	AmountsOff map[string]string `json:"amountsOff,omitempty"`
	// Invoice line kinds: base, addon, usage.
	AppliesTo []string `json:"appliesTo,omitempty"`
	// Plan asset_category values that qualify, such as compute. Empty means any.
	AssetCategories []string `json:"assetCategories,omitempty"`
	// Plan asset_type values that qualify, such as vm or gameserver. Empty means any.
	AssetTypes []string `json:"assetTypes,omitempty"`
	// USD top-up needed before a redeemed credit lot can be spent. Only set for
	// credit coupons that require one.
	CreditMinTopup string `json:"creditMinTopup,omitempty"`
	// Days a redeemed credit lot stays valid. Only set for credit coupons.
	CreditValidDays int32  `json:"creditValidDays,omitempty"`
	Description     string `json:"description,omitempty"`
	// - COUPON_DISCOUNT_TYPE_CREDIT: A code that grants promotional credit instead of discounting a subscription.
	DiscountType CouponDiscountType `json:"discountType,omitempty"`
	// - COUPON_DURATION_ONCE: Discounts the next invoice only.
	//  - COUPON_DURATION_REPEATING: Discounts duration_in_periods invoices, or every invoice for duration_days.
	Duration              CouponDuration `json:"duration,omitempty"`
	DurationDays          int32          `json:"durationDays,omitempty"`
	DurationInPeriods     int32          `json:"durationInPeriods,omitempty"`
	FirstTimeCustomerOnly bool           `json:"firstTimeCustomerOnly,omitempty"`
	// - COUPON_FUNDING_PLATFORM: The platform funds the discount. The code applies across providers, and
	// each provider still receives the amount they were owed.
	FundedBy CouponFunding `json:"fundedBy,omitempty"`
	HighRisk bool          `json:"highRisk,omitempty"`
	ID       string        `json:"id,omitempty"`
	// ISO currency to per-invoice cap for percentage coupons.
	MaxDiscountAmounts map[string]string `json:"maxDiscountAmounts,omitempty"`
	// 0 means unlimited.
	MaxRedemptions  int32  `json:"maxRedemptions,omitempty"`
	Name            string `json:"name,omitempty"`
	OncePerCustomer bool   `json:"oncePerCustomer,omitempty"`
	// Decimal string in (0, 100] for percentage coupons.
	PercentOff       string        `json:"percentOff,omitempty"`
	PlanIDs          []string      `json:"planIds,omitempty"`
	Status           Protov1Status `json:"status,omitempty"`
	TimesRedeemed    int32         `json:"timesRedeemed,omitempty"`
	Timestamps       *Timestamps   `json:"timestamps,omitempty"`
	UsageMetricCodes []string      `json:"usageMetricCodes,omitempty"`
	ValidFrom        *time.Time    `json:"validFrom,omitempty"`
	ValidUntil       *time.Time    `json:"validUntil,omitempty"`
}

